const Distances testdistances("BondLength.ini");
struct FMIC_TS {
	std::array<cpplib::basic_types::FloatingPointType, 6> cell;
	std::vector<const char*> symm;
	std::vector<AtomTypeBase> types;
	std::vector<PointType> points;
	FMIC_TS(std::array<cpplib::basic_types::FloatingPointType, 6>& cell_in, std::vector<const char*>& symm_in,
					  std::vector<AtomTypeBase>& types_in, std::vector<FloatingPointType>& xyz_in) :
		cell(std::move(cell_in)),
		symm(std::move(symm_in)),
		types(std::move(types_in)) {
		for (size_t i = 0; i < types.size(); i++) {
			points.emplace_back(xyz_in[3 * i], xyz_in[3 * i + 1], xyz_in[3 * i + 2]);
		}
	}
	inline auto call() {
		return FindMoleculesInCell(cell, symm, types, points);
	}
	inline auto compaq() {
		return Compaq(cell, symm, types, points);
	}
	inline auto cluster(const std::vector<FloatingPointType>& p, cpplib::basic_types::FloatingPointType r2, bool& b) {
		std::vector<cpplib::Cluster::AnchorType> anch;
		auto s = p.size() / 4;
		for (size_t i = 0; i < s; i++) {
			anch.emplace_back(PointType(p[4 * i], p[4 * i + 1], p[4 * i + 2]), p[4 * i + 3]);
		}
		return ClusterCreate(cell, symm, types, points, anch, r2, b);
	}
};

