	for (size_t i = 0; i < arg.size(); i++) {
		atoms.emplace_back(std::get<0>(arg[i]));
		points.emplace_back(std::get<1>(arg[i]), std::get<2>(arg[i]), std::get<3>(arg[i]));
	}
	bool mvtc = false;

	std::vector<const char*> symms{"x+1,y,z","x-1,y,z", "x,y+1,z"};
